const listAccountDeletionConflicts = `-- name: ListAccountDeletionConflicts :many
SELECT workspace.name
FROM public.workspace_members AS own
JOIN public.workspaces AS workspace ON workspace.workspace_id = own.workspace_id
WHERE own.user_id = $1 AND own.role = 'admin' AND workspace.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM public.workspace_members AS other
      JOIN public.users AS account ON account.user_id = other.user_id
      WHERE other.workspace_id = own.workspace_id AND other.user_id <> own.user_id
        AND other.role = 'admin' AND account.is_active = TRUE AND account.is_system = FALSE
  )
ORDER BY workspace.name, workspace.workspace_id
`

type ListAccountDeletionConflictsParams struct {
	UserID uuid.UUID
}

func (q *Queries) ListAccountDeletionConflicts(ctx context.Context, arg ListAccountDeletionConflictsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listAccountDeletionConflicts, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

