const lockAccountDeletionMemberships = `-- name: LockAccountDeletionMemberships :many
SELECT member.workspace_id, member.user_id
FROM public.workspace_members AS member
WHERE member.workspace_id IN (
    SELECT own.workspace_id FROM public.workspace_members AS own WHERE own.user_id = $1
)
ORDER BY member.workspace_id, member.user_id
FOR UPDATE OF member
`

type LockAccountDeletionMembershipsParams struct {
	UserID uuid.UUID
}

type LockAccountDeletionMembershipsRow struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
}

// Lock all memberships in affected workspaces, not only the deleting member.
// Together with SERIALIZABLE isolation this prevents concurrent last-admin exits.
func (q *Queries) LockAccountDeletionMemberships(ctx context.Context, arg LockAccountDeletionMembershipsParams) ([]LockAccountDeletionMembershipsRow, error) {
	rows, err := q.db.Query(ctx, lockAccountDeletionMemberships, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockAccountDeletionMembershipsRow{}
	for rows.Next() {
		var i LockAccountDeletionMembershipsRow
		if err := rows.Scan(&i.WorkspaceID, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

