// This prevents a previously queued update from recreating an erased contact.
func (q *Queries) LockAccountSubscriberLifecycle(ctx context.Context, arg LockAccountSubscriberLifecycleParams) error {
	_, err := q.db.Exec(ctx, lockAccountSubscriberLifecycle, arg.Email)
	return err
}

