const reattributeAccountNotifications = `-- name: ReattributeAccountNotifications :exec
UPDATE public.notifications
SET actor_id = $1,
    message = CASE WHEN jsonb_typeof(message #> '{variables,actor}') = 'object'
        THEN jsonb_set(message, '{variables,actor,value}', to_jsonb(CAST('Former user' AS text)))
        ELSE message END
WHERE actor_id = $2 AND recipient_id <> $2
`

